        template <class VelocitySet, const nodeType_t BoundaryCase>
        __device__ __host__ inline constexpr void applyDirichlet(momentsArray &moments, const thread::array<scalar_t, VelocitySet::Q()> &pop) noexcept
        {
            applyDirichlet<VelocitySet, BoundaryCase>(moments, incomingMoments<VelocitySet, BoundaryCase>(pop));
        }

        template <const nodeType_t BoundaryCase>
        __device__ __host__ [[nodiscard]] inline constexpr void applyVelocityProfile(momentsArray &moments) noexcept
        {
            if constexpr (BoundaryCase == normalVectorBase::SOUTH_WEST_BACK())
            {
                moments[q_i<1>()] = (device::U_West[0] + device::U_South[0] + device::U_Back[0]) / static_cast<scalar_t>(3);
                moments[q_i<2>()] = (device::U_West[1] + device::U_South[1] + device::U_Back[1]) / static_cast<scalar_t>(3);
                moments[q_i<3>()] = (device::U_West[2] + device::U_South[2] + device::U_Back[2]) / static_cast<scalar_t>(3);
